void Solver::bump_var(int var, double coeff) {
    // Compute increment and update activity
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Rescale if activity exceeds safe threshold to avoid overflow
    const double MAX_ACTIVITY = 1e100;
    if (activity[var] > MAX_ACTIVITY) {
        const double SCALE = 1e-100;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= SCALE;
        }
        var_inc *= SCALE;
    }

    // Keep VSIDS heap consistent: update if present, otherwise insert
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
